<?php
declare(strict_types=1);
require dirname(__DIR__,2).'/vendor/autoload.php';
use App\Bootstrap\App; use App\Database\Database; use App\Modules\Platform\PlatformRepository; use App\Support\PlatformAuth; use function App\Support\e;
new App(); $db=Database::connection(); $platformUser=PlatformAuth::requireAdmin($db); $repo=new PlatformRepository($db);
function platformStatus(?string $status): string { return match($status){ 'active','paid'=>'status-active','trial'=>'status-trial','pending','past_due'=>'status-past_due','failed','expired','cancelled','suspended','refunded'=>'status-expired',default=>'status-draft'}; }
$page=max(1,(int)($_GET['page']??1)); $result=$repo->auditLogs($page,30); ob_start(); ?><section class="platform-panel"><div class="platform-panel-head"><div><h2>Audit log</h2><p>Administrative actions across the Dukame platform.</p></div><span class="platform-muted"><?= number_format($result['total']) ?> events</span></div><div class="table-responsive"><table class="table platform-table align-middle mb-0"><thead><tr><th>When</th><th>Administrator</th><th>Action</th><th>Summary</th><th>Entity</th><th>IP</th></tr></thead><tbody><?php if(!$result['items']): ?><tr><td colspan="6"><div class="platform-empty">No audit events yet.</div></td></tr><?php endif; ?><?php foreach($result['items'] as $r): ?><tr><td class="platform-muted"><?= e(date('d M Y H:i',strtotime($r['created_at']))) ?></td><td><div class="fw-semibold"><?= e(trim(($r['first_name']??'').' '.($r['last_name']??'')) ?: 'System') ?></div><div class="platform-muted"><?= e($r['role']??'') ?></div></td><td><code><?= e($r['action']) ?></code></td><td><?= e($r['summary']) ?></td><td><?= e($r['entity_type']??'—') ?><?= $r['entity_id']?' #'.(int)$r['entity_id']:'' ?></td><td class="platform-muted"><?= e($r['ip_address']??'—') ?></td></tr><?php endforeach; ?></tbody></table></div><?php if($result['pages']>1): ?><div class="p-3 border-top d-flex justify-content-between"><span class="platform-muted">Page <?= $result['page'] ?> of <?= $result['pages'] ?></span><div class="d-flex gap-1"><?php if($result['page']>1): ?><a class="btn btn-sm btn-light border" href="?page=<?= $result['page']-1 ?>">Previous</a><?php endif; ?><?php if($result['page']<$result['pages']): ?><a class="btn btn-sm btn-light border" href="?page=<?= $result['page']+1 ?>">Next</a><?php endif; ?></div></div><?php endif; ?></section><?php $content=ob_get_clean();$title='Audit Log';$platformSection='audit';require dirname(__DIR__,2).'/app/Views/layouts/platform.php';
